import{_ as t,o,c as a,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"1994年 · 规模之敌","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1994年.md","filePath":"05_quotes/by-year/1994年.md"}'),r={name:"05_quotes/by-year/1994年.md"};function u(s,e,c,h,q,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_1994年-·-规模之敌" tabindex="-1">1994年 · 规模之敌 <a class="header-anchor" href="#_1994年-·-规模之敌" aria-label="Permalink to &quot;1994年 · 规模之敌&quot;">​</a></h1><blockquote><p>鼓鼓的钱包是卓越投资成果的敌人。——巴菲特（64岁）</p></blockquote><p>本页收录1994年致股东信中的经典语录。本年巴菲特坦诚规模是业绩的最大敌人，以Scott Fetzer为案例深入剖析了内在价值与账面价值的本质区别，并首次详述了薪酬设计应如何真正实现管理层与股东的利益对齐。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>鼓鼓的钱包是卓越投资成果的敌人。</p></blockquote><blockquote><p>泰德·威廉姆斯解释了原因：&quot;我的论点是，要成为一个优秀的击球手，你必须等到好球才挥棒。如果我必须去追逐我&#39;快乐区域&#39;之外的球，我就不会是一个打击率.344的击球手。我可能只是一个打击率.250的击球手。&quot;查理和我表示赞同，并将努力等待那些完全在我们自己&#39;快乐区域&#39;内的机会。</p></blockquote><blockquote><p>我们将继续无视政治和经济预测，这对许多投资者和商人来说是一种昂贵的干扰。恐惧是潮流追随者的敌人，却是基本面分析者的朋友。</p></blockquote><blockquote><p>在投资中，不需要做非凡的事情就能获得非凡的结果。在后来的生活中，我惊讶地发现这句话在企业管理中也同样适用。</p></blockquote><blockquote><p>遵循韦恩·格雷茨基的建议：&quot;去冰球将要去的地方，而不是它现在所在的地方。&quot;</p></blockquote><blockquote><p>当&quot;愚蠢&quot;的资金承认其局限性时，它就不再愚蠢了。</p></blockquote><blockquote><p>拥有一大部分希望钻石远胜于拥有100%的莱茵石。</p></blockquote><blockquote><p>投资者应该记住，他们的记分卡不是用奥运跳水方法计算的：难度系数不算数。</p></blockquote><blockquote><p>因为对经济或股市的短期担忧而放弃购买一家长期未来可预测的优秀企业的股票，是愚蠢的，因为经济或股市我们知道是不可预测的。为什么要因为一个无知的猜测而放弃一个有知的决定呢？</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1994年伯克希尔每股账面价值增长13.9%，30年复合增长率23%。巴菲特坦承随着资本规模膨胀，未来表现将远无法与过去相提并论。本年USAir优先股投资被大幅减记75%，巴菲特将其称为&quot;非受迫性失误&quot;，深刻反思了航空业成本结构的不可持续性。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1994年-翻译-·-01-letters-1994年-核心总结-·-01-letters-1994年-思维导图" tabindex="-1"><a href="/01_letters/1994年/翻译.html">01_letters/1994年/翻译</a> · <a href="/01_letters/1994年/核心总结.html">01_letters/1994年/核心总结</a> · <a href="/01_letters/1994年/思维导图.html">01_letters/1994年/思维导图</a> <a class="header-anchor" href="#_01-letters-1994年-翻译-·-01-letters-1994年-核心总结-·-01-letters-1994年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1994年/翻译]] · [[→ 核心总结|01_letters/1994年/核心总结]] · [[→ 思维导图|01_letters/1994年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1994年/翻译.html">/01_letters/1994年/翻译</a></li></ul>',22)])])}const p=t(r,[["render",u]]);export{b as __pageData,p as default};
